using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering.Universal;

public sealed partial class DefenseGame {
 CivilizationModel civilization;FrontierArt frontierArt;CivilizationScene civilizationScene;
 bool civilOpen,civilQA,civilRecord,civilPlacing;int civilTab,civilSelection,civilPaint,civilPlaceKind;float civilSaveClock,civilPlacementYaw,civilFollowTime;Vector3 civilPlaceNormal;bool civilPlaceValid;string civilPlaceReason="";
 Transform civilDesign;Material civilCoating;CivilRocket civilFollow;readonly List<CivilRocket> civilRockets=new List<CivilRocket>();
 sealed class CivilRocket {public OrbitDemo.State state;public string key;public Transform root;public LineRenderer flame;public float age,maxAltitude;public bool credited;}
 float HullMaximum{get{return 100+tiers[1]*25+(civilization==null?0:CivilizationModel.HullHealth[civilization.blueprint]);}}
 bool CivilEnabled{get{return civilization!=null;}}
 string CivilizationPath{get{return Path.Combine(Application.persistentDataPath,"wayfarer-civilization-v1.json");}}
 void InitializeCivilization(string[] args){
  civilQA=Array.IndexOf(args,"--civilization-qa")>=0;civilRecord=Array.IndexOf(args,"--civilization-record")>=0;
  if(legacyUniverse||qa&&!civilQA&&!civilRecord)return;
  civilization=new CivilizationModel();if(!qa&&!automatedPlayback){var loaded=ReadCivilization(CivilizationPath);if(loaded!=null)civilization=loaded;}
  frontierArt=new FrontierArt();civilPaint=civilization.paint;civilizationScene=gameObject.AddComponent<CivilizationScene>();civilizationScene.Initialize(this,frontierArt,expedition);
  ApplyCivilHull();health=HullMaximum;foreach(var sectorEntry in sectors.Values){var sun=sectorEntry.root.transform.Find("Sun / unlandable light source");if(sun!=null)sun.GetComponent<Renderer>().sharedMaterial=new Material(frontierArt.star);}civilizationScene.Sync(civilization,Pos(player));
  if(civilQA)StartCoroutine(CivilizationChecks());else if(civilRecord)StartCoroutine(CivilizationRecord());else OpenCivilization(0);
 }
 static CivilizationModel ReadCivilization(string path){foreach(string file in new[]{path,path+".backup"})try{if(!File.Exists(file)||new FileInfo(file).Length>2*1024*1024)continue;var data=JsonUtility.FromJson<CivilizationModel>(File.ReadAllText(file));if(data!=null&&data.Validate())return data;}catch(Exception){ }return null;}
 static void WriteCivilization(string path,CivilizationModel model){if(!model.Validate())throw new InvalidDataException();Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".pending";File.WriteAllText(temp,JsonUtility.ToJson(model,true));if(File.Exists(path)){bool valid=false;try{var previous=JsonUtility.FromJson<CivilizationModel>(File.ReadAllText(path));valid=previous!=null&&previous.Validate();}catch(Exception){}File.Replace(temp,path,valid?path+".backup":null);}else File.Move(temp,path);}
 bool SaveCivilization(){if(civilization==null||qa||automatedPlayback)return false;try{WriteCivilization(CivilizationPath,civilization);civilSaveClock=0;return true;}catch(Exception e){Debug.LogWarning("Civilization save unavailable: "+e.GetType().Name);return false;}}
 void OnApplicationQuit(){SaveCivilization();}
 void OnApplicationPause(bool state){if(state)SaveCivilization();}
 void ApplyCivilHull(){if(civilization==null)return;if(civilDesign!=null)Destroy(civilDesign.gameObject);if(civilCoating!=null)Destroy(civilCoating);civilCoating=frontierArt.Coating(civilization.paint);
  foreach(Transform t in rocket){if(t==modules||t==rocketFlame||t.name=="Landing gear"||t.name=="SIX WHEEL SURFACE CONVERSION"||t.name=="Civilization hull")continue;foreach(var r in t.GetComponentsInChildren<Renderer>())r.enabled=false;}
  civilDesign=new GameObject("Civilization hull").transform;civilDesign.SetParent(rocket,false);frontierArt.Hull(civilDesign,civilization.blueprint,civilCoating);civilPaint=civilization.paint;
 }
 void OpenCivilization(int tab){if(civilization==null||inTidal||outcome!=""||HelmetPhotoUI.BlocksControls)return;civilTab=Mathf.Clamp(tab,0,5);civilSelection=0;civilOpen=true;civilPlacing=false;paused=true;upgradeOpen=chartOpen=false;if(surface!=null)surface.Journal=false;releaseFire=true;playerAction=Vector3.zero;Controls.SuppressUntilNeutral();Cursor.lockState=CursorLockMode.None;Cursor.visible=true;if(civilizationScene!=null)civilizationScene.Preview(civilTab,0,civilPaint,civilization);}
 void CloseCivilization(){civilOpen=false;civilizationScene.HidePreview();releaseFire=true;SaveCivilization();ResumeFlight();}
 int CivilRows(){if(civilTab==1)return Mathf.Max(1,civilization.Recommendations().Count);if(civilTab==2)return 8;if(civilTab==3)return 4;if(civilTab==4)return 4;return 1;}
 bool CivilMenuInput(){if(civilization==null)return false;
  if(civilFollow!=null&&civilFollowTime>0&&(GameKeyDown(KeyCode.Backspace)||PadDown(PilotInput.Button.Circle))){civilFollowTime=0;return true;}
  bool toggle=GameKeyDown(KeyCode.B)||(GroundActive?PadDown(PilotInput.Button.Down):PadDown(PilotInput.Button.L3));
  if(!civilOpen&&toggle){OpenCivilization(0);return true;}
  if(civilOpen){civilizationScene.AnimatePreview(Mathf.Min(Time.unscaledDeltaTime,.1f),Controls.Look);int oldTab=civilTab,oldSelection=civilSelection,oldPaint=civilPaint;if(GameKeyDown(KeyCode.Escape)||PadDown(PilotInput.Button.Circle)||PadDown(PilotInput.Button.Options)||GameKeyDown(KeyCode.B)){CloseCivilization();return true;}
   if(GameKeyDown(KeyCode.RightArrow)||PadDown(PilotInput.Button.R1)||PadDown(PilotInput.Button.Right)){civilTab=(civilTab+1)%6;civilSelection=0;}
   if(GameKeyDown(KeyCode.LeftArrow)||PadDown(PilotInput.Button.L1)||PadDown(PilotInput.Button.Left)){civilTab=(civilTab+5)%6;civilSelection=0;}
   if(GameKeyDown(KeyCode.DownArrow)||PadDown(PilotInput.Button.Down))civilSelection=(civilSelection+1)%CivilRows();
   if(GameKeyDown(KeyCode.UpArrow)||PadDown(PilotInput.Button.Up))civilSelection=(civilSelection+CivilRows()-1)%CivilRows();
   if(civilTab==3&&(GameKeyDown(KeyCode.C)||PadDown(PilotInput.Button.Square)))civilPaint=(civilPaint+1)%4;
   if(civilTab==2&&civilSelection==5&&(GameKeyDown(KeyCode.L)||PadDown(PilotInput.Button.Square))){LaunchCivilRocket();return true;}
   if(civilTab==4&&PadDown(PilotInput.Button.Square)){if(civilization.wars.Exists(w=>!w.resolved))CivilNavigateWar();else if(civilSelection<3)CivilNavigateFaction(civilSelection);return true;}
   if(oldTab!=civilTab||oldSelection!=civilSelection||oldPaint!=civilPaint)civilizationScene.Preview(civilTab,civilSelection,civilPaint,civilization);
   if(GameKeyDown(KeyCode.Return)||PadDown(PilotInput.Button.Cross)){CivilPrimary();Controls.SuppressUntilNeutral();}
   if(PadDown(PilotInput.Button.Triangle)||GameKeyDown(KeyCode.G))CivilSecondary();return true;
  }
  if(civilPlacing){if(PadDown(PilotInput.Button.L1)){civilPlacementYaw+=15;CivilPlacement();return true;}if(GameKeyDown(KeyCode.Escape)||PadDown(PilotInput.Button.Circle)){civilPlacing=false;civilizationScene.HideGhost();releaseFire=true;return true;}if(GameKeyDown(KeyCode.Q))civilPlacementYaw-=15;if(GameKeyDown(KeyCode.R))civilPlacementYaw+=15;CivilPlacement();if(GameKeyDown(KeyCode.E)||PadDown(PilotInput.Button.R1))ConfirmDistrict();}
  return false;
 }
 CivilizationModel.Colony CivilLocal {get{if(civilization==null||expedition==null)return null;var p=expedition.Nearest(GroundActive?expedition.Focus:Pos(player));return p==null?null:civilization.Find(p.key);}}
 void BeginCivilExploration(){CloseCivilization();if(civilization.Level==0&&!GroundActive&&!RoverDeployed){landingAssist=true;cruising=false;throttle=0;}}
 void CivilPrimary(){string why;
  if(civilTab==0){BeginCivilExploration();return;}
  if(civilTab==1){var goals=civilization.Recommendations();if(goals.Count==0)return;var g=goals[Mathf.Clamp(civilSelection,0,goals.Count-1)];civilization.activeGoal=g.id;civilization.CheckGoal();Notice("ORACLE / "+g.title+" / "+g.why);SaveCivilization();return;}
  if(civilTab==2){if(!GroundActive){Notice("Land, disembark, then place a city district.");return;}var p=expedition.Nearest(expedition.Focus);if(!civilization.CanBuild(civilSelection,civilization.Find(p.key),out why)){Notice(why);return;}civilPlaceKind=civilSelection;civilPlacing=true;civilOpen=false;ResumeFlight();releaseFire=true;Controls.SuppressUntilNeutral();civilizationScene.HidePreview();CivilPlacement();return;}
  if(civilTab==3){if(cruising||inTidal||RoverDeployed||Vel(player).magnitude>3){Notice("Park the craft or stop below 3 m/s before changing hulls.");return;}if(!civilization.BuyHull(civilSelection,out why)){Notice(why);return;}float fraction=health/HullMaximum;civilization.blueprint=civilSelection;civilization.paint=civilPaint;health=fraction*HullMaximum;ApplyCivilHull();Notice("SHIPWRIGHT / "+CivilizationModel.HullNames[civilSelection]+" equipped");SaveCivilization();return;}
  if(civilTab==4){if(civilSelection==3){if(civilization.BuyFleet(out why))Notice("Orbital shipyard / one warship added to reserve");else Notice(why);}
   else{int source=civilization.colonies.Count==0?0:civilization.colonies[0].port;var war=civilization.Strike(civilSelection,source,false,out why);if(war!=null)InitializeCivilWarRoute(war);Notice(war==null?why:"FLEET DEPARTED / "+civilization.factions[civilSelection].name+" / "+war.travel.ToString("F0")+"s to front");}SaveCivilization();return;}
  if(civilTab==5){if(civilization.BeginDyson(civilization.dysonBuilt>0?civilization.dysonSystem:chartSystem,out why))Notice("DYSON PROJECT / collector sector construction started");else Notice(why);SaveCivilization();}
 }
 void CivilSecondary(){string why;if(civilTab==2){var c=CivilLocal;if(civilSelection==5){if(!civilization.FabricateRocket(c,out why))Notice(why);else Notice("AURORA ROCKET / assembly started at local launch complex");}else if(civilSelection==6){if(!civilization.BuyFleet(out why))Notice(why);else Notice("New warship ready in fleet reserve");}SaveCivilization();}
  else if(civilTab==4&&civilSelection<3){if(!civilization.Diplomacy(civilSelection,out why))Notice(why);else Notice("Envoy delivered / relations improved by 35");SaveCivilization();}
  else if(civilTab==5)CivilNavigateStar();
 }
 void CivilPlacement(){if(!GroundActive){civilPlacing=false;civilizationScene.HideGhost();return;}var p=expedition.Nearest(expedition.Focus);Vector3 up=(expedition.Focus-p.body.P).normalized;Vector3 forward=PlanetExpedition.SurfaceTangent(up,cam.transform.forward);float range=frontierArt.Radius(civilPlaceKind)+18;Vector3 candidate=expedition.Focus+forward*range;civilPlaceNormal=(candidate-p.body.P).normalized;civilPlaceValid=ValidateDistrict(p,civilPlaceNormal,civilPlaceKind,out civilPlaceReason);civilizationScene.Ghost(p,civilPlaceNormal,civilPlaceKind,civilPlacementYaw,civilPlaceValid);}
 bool ValidateDistrict(PlanetExpedition.Planet p,Vector3 normal,int kind,out string why){var c=civilization.Find(p.key);var port=ports.Find(x=>x.key==p.key);var owner=port==null?null:civilization.factions.Find(f=>f.port==port.system*4+port.index);if(c==null&&owner!=null&&owner.relation<70){why=owner.name+" territory / negotiate a treaty or win the orbital front";return false;}if(!civilization.CanBuild(kind,c,out why))return false;if(c!=null&&Vector3.Distance(normal*(float)p.body.radius,c.anchor*(float)p.body.radius)>1600){why="Place within 1.6 km of this planet's command spire";return false;}Vector3 at=normal*((float)p.body.radius+PlanetExpedition.Height(normal,p.body.seed,p.body.radius));float radius=frontierArt.Radius(kind);
  if(c!=null)foreach(var d in c.districts){Vector3 other=d.normal*((float)p.body.radius+PlanetExpedition.Height(d.normal,p.body.seed,p.body.radius));if(Vector3.Distance(at,other)<radius+frontierArt.Radius(d.kind)+5){why="Leave room between district foundations";return false;}}
  Vector3 t=PlanetExpedition.SurfaceTangent(normal,Vector3.right);float h=PlanetExpedition.Height(normal,p.body.seed,p.body.radius);foreach(Vector3 v in new[]{t,-t,Vector3.Cross(normal,t),-Vector3.Cross(normal,t)}){float sample=PlanetExpedition.Height((at+v*radius).normalized,p.body.seed,p.body.radius);if(Mathf.Abs(sample-h)>8){why="Find flatter terrain for this foundation";return false;}}
  Vector3 world=p.body.P+at;if(Vector3.Distance(world,Pos(player))<radius+4){why="Keep your ship outside the foundation";return false;}why="Foundation clear / confirm construction";return true;
 }
 bool ConfirmDistrict(){if(!civilPlacing||!GroundActive||!civilPlaceValid){Notice(civilPlaceReason);return false;}var p=expedition.Nearest(expedition.Focus);if(!ValidateDistrict(p,civilPlaceNormal,civilPlaceKind,out civilPlaceReason)){Notice(civilPlaceReason);return false;}var port=ports.Find(x=>x.key==p.key);string why;var district=civilization.Build(civilPlaceKind,p.key,p.name,port==null?0:port.system*4+port.index,civilPlaceNormal,civilPlacementYaw,out why);if(district==null){Notice(why);return false;}civilizationScene.Sync(civilization,expedition.Focus);civilPlacing=false;civilizationScene.HideGhost();releaseFire=true;Notice("CONSTRUCTION / "+CivilizationModel.DistrictNames[district.kind]+" / "+CivilizationModel.BuildSeconds[district.kind]+"s");SaveCivilization();return true;}
 void CivilReward(int points,int parts){if(civilization==null)return;civilization.alloy=Mathf.Min(1000000,civilization.alloy+parts*5);civilization.science=Mathf.Min(1000000,civilization.science+points*.018f);}
 void CivilTick(float delta){if(civilization==null)return;float dt=Mathf.Clamp(delta,0,.1f);bool active=!paused&&!civilOpen&&!upgradeOpen&&outcome==""&&!chartOpen&&!HelmetPhotoUI.BlocksControls;
  if(active){foreach(var front in civilization.wars)if(!front.resolved&&!front.routed)InitializeCivilWarRoute(front);int previousLevel=civilization.Level;string previousGoal=civilization.activeGoal;civilization.Tick(dt,CivilBattleLoaded);if(civilization.Level>previousLevel){Notice("A NEW AGE / "+civilization.LevelName+" civilization");SaveCivilization();}else if(previousGoal!=""&&civilization.activeGoal==""){Notice("ORACLE / milestone complete / resources and influence awarded");SaveCivilization();}CivilWarTick(dt);CivilRocketTick(dt);civilSaveClock+=dt;if(civilSaveClock>20)SaveCivilization();}
  civilizationScene.Tick(dt,civilization,GroundActive?expedition.Focus:Pos(player),active);if(civilPlacing)CivilPlacement();
 }
 void CivilShift(Vector3 shift){civilFilmAt-=shift;civilFilmLook-=shift;if(civilizationScene!=null)civilizationScene.Shift(shift);foreach(var r in civilRockets){MoveState(ref r.state,shift);r.root.position-=shift;}CivilWarShift(shift);}
 void CivilResetFlight(){if(civilization==null)return;civilOpen=false;civilPlacing=false;civilFollow=null;civilFollowTime=0;civilizationScene.HideGhost();civilizationScene.HidePreview();civilizationScene.ResetTraffic();foreach(var unit in civilUnits)if(unit.root!=null)Destroy(unit.root.gameObject);civilUnits.Clear();foreach(var bolt in civilBolts)if(bolt.view!=null)Destroy(bolt.view.gameObject);civilBolts.Clear();foreach(var flight in civilRockets)if(flight.root!=null)Destroy(flight.root.gameObject);civilRockets.Clear();health=HullMaximum;}
 void CivilContacts(){if(civilizationScene==null||civilization==null)return;if(GroundActive){Vector3 p=civilizationScene.Resolve(expedition.Focus,.6f);expedition.ResolveStructure(p);}else if(expedition.Alt(Pos(player))<80){Vector3 before=Pos(player),after=civilizationScene.Resolve(before,RoverDeployed?1.7f:1.1f);if(after!=before){player.x=after.x;player.y=after.y;player.z=after.z;Vector3 n=(after-before).normalized,v=Vel(player);v-=n*Mathf.Min(0,Vector3.Dot(v,n));player.vx=v.x;player.vy=v.y;player.vz=v.z;}}}
 bool LaunchCivilRocket(){var colony=CivilLocal;if(colony==null){Notice("Approach your colony's launch complex");return false;}var p=expedition.planets.Find(x=>x.key==colony.key);if(p==null||Vector3.Distance(GroundActive?expedition.Focus:Pos(player),p.body.P+colony.anchor*(float)p.body.radius)>2200){Notice("Move within 2.2 km of your colony to supervise launch");return false;}if(!civilization.TakeRocket(colony)){Notice("Fabricate a rocket first / select launch complex and press G or Triangle");return false;}
  var pad=colony.districts.Find(d=>d.kind==5&&d.ready);Vector3 up=pad.normal;Vector3 at=p.body.P+up*((float)p.body.radius+PlanetExpedition.Height(up,p.body.seed,p.body.radius)+2.5f);var root=frontierArt.Rocket(null);root.position=at;root.rotation=Quaternion.FromToRotation(Vector3.up,up);var flame=new GameObject("Native rocket / exhaust plume").AddComponent<LineRenderer>();flame.transform.SetParent(root,false);flame.useWorldSpace=false;flame.positionCount=2;flame.SetPositions(new[]{Vector3.up,Vector3.down*12});flame.startWidth=1.2f;flame.endWidth=4;flame.sharedMaterial=frontierArt.beamOrange;var flight=new CivilRocket{state=Make(at,Vector3.zero),key=p.key,root=root,flame=flame};civilRockets.Add(flight);civilFollow=flight;civilFollowTime=18;Notice("AURORA / ignition / native ascent / survey credited above 1 km");CloseCivilization();SaveCivilization();return true;
 }
 void CivilRocketTick(float dt){for(int i=civilRockets.Count-1;i>=0;i--){var r=civilRockets[i];r.age+=dt;var p=expedition.planets.Find(x=>x.key==r.key);if(p==null){Destroy(r.root.gameObject);civilRockets.RemoveAt(i);continue;}Vector3 up=(Pos(r.state)-p.body.P).normalized;for(float step=0;step<dt-.00001f;step+=.01f){float h=Mathf.Min(.01f,dt-step);Vector3 thrust=up*(Gravity(Pos(r.state)).magnitude+(r.age<2?8:24));Step(ref r.state,thrust,h);}r.root.position=Pos(r.state);r.root.rotation=Quaternion.FromToRotation(Vector3.up,up);float altitude=expedition.Alt(Pos(r.state));r.maxAltitude=Mathf.Max(altitude,r.maxAltitude);r.flame.SetPosition(1,Vector3.down*(10+Mathf.Sin(r.age*44)*2));if(!r.credited&&altitude>1000){r.credited=true;civilization.launches++;civilization.science+=80;civilization.CheckGoal();Notice("SURVEY ROCKET / 1 km reached / +80 science / civilization milestone");SaveCivilization();}if(r.age>38||r.state.captured!=0){if(civilFollow==r)civilFollow=null;Destroy(r.root.gameObject);civilRockets.RemoveAt(i);}}}
 void CivilCamera(float delta){if(civilFilmCamera){Vector3 photoAt=civilFilmAt;var nearest=expedition.Nearest(photoAt);float clearance=expedition.Alt(photoAt);if(clearance<25)photoAt+=(photoAt-nearest.body.P).normalized*(25-clearance);cam.transform.position=photoAt;cam.transform.rotation=Quaternion.LookRotation(civilFilmLook-photoAt,ShipUp);return;}if(civilFollow==null||civilFollowTime<=0||civilization==null)return;if(!paused)civilFollowTime-=delta;if(GameKeyDown(KeyCode.Backspace)||PadDown(PilotInput.Button.Circle)){civilFollowTime=0;return;}var p=expedition.Nearest(civilFollow.root.position);Vector3 up=(civilFollow.root.position-p.body.P).normalized,t=PlanetExpedition.SurfaceTangent(up,ShipForward);Vector3 goal=civilFollow.root.position-t*65+up*23;cam.transform.position=Vector3.Lerp(cam.transform.position,goal,1-Mathf.Exp(-delta*3));cam.transform.rotation=Quaternion.LookRotation(civilFollow.root.position+up*5-cam.transform.position,up);}
 public string CivilPortKey(int index){return ports[Mathf.Clamp(index,0,ports.Count-1)].key;}
 void InitializeCivilWarRoute(CivilizationModel.War war){war.travel=Mathf.Max(24,WorldDistance(ports[war.source].global,ports[civilization.factions[war.enemy].port].global)/1450+14);war.routed=true;}
 bool CivilRoute(GalacticPoint goal,string title,Port destination=null,Vector3 normal=default(Vector3)){
  if(GroundActive||RoverDeployed){Notice("Board and retract tires before setting a course");return false;}var near=expedition.Nearest(Pos(player));if(expedition.Alt(Pos(player))<near.body.atmosphere+80){Notice("Climb clear of the atmosphere before engaging cruise");return false;}
  if(civilOpen)CloseCivilization();routeWaypoints.Clear();routeLeg=0;GalacticPoint current=GlobalPosition;GalacticPoint center=OriginGlobal+near.body.P;Vector3 up=(current-center).normalized,outgoing=(goal-center).normalized;float safe=(float)near.body.radius+Mathf.Max(1600,(float)near.body.atmosphere*2);
  if(expedition.Alt(Pos(player))<3500){routeWaypoints.Add(center+up*safe);int arcs=Mathf.Max(1,Mathf.CeilToInt(Vector3.Angle(up,outgoing)/35));for(int k=1;k<=arcs;k++)routeWaypoints.Add(center+Vector3.Slerp(up,outgoing,k/(float)arcs)*safe);}
  if(destination!=null){Vector3 inbound=(current-destination.global).normalized;float arrivalRadius=destination.radius+2100;routeWaypoints.Add(destination.global+inbound*arrivalRadius);int arcs=Mathf.Max(1,Mathf.CeilToInt(Vector3.Angle(inbound,normal)/35));for(int k=1;k<=arcs;k++)routeWaypoints.Add(destination.global+Vector3.Slerp(inbound,normal,k/(float)arcs)*arrivalRadius);}
  routeGlobal=goal;routeWaypoints.Add(goal);destinationName=title;cruising=true;paused=false;chartOpen=false;landingAssist=cruiseBraking=false;releaseFire=true;Notice("Cruise / "+title+" / arrival brakes automatically");return true;
 }
 void CivilNavigateStar(){int system=civilization.dysonBuilt>0||civilization.dysonWorking?civilization.dysonSystem:chartSystem;var target=catalog[system].location+new Vector3(-20000,10000,-75000);CivilRoute(target+new Vector3(0,0,6800),catalog[system].name+" / DYSON PROJECT");}
 void CivilNavigateWar(){var war=civilization.wars.Find(w=>!w.resolved);if(war==null){Notice("No active orbital front");return;}chartSystem=war.target/4;chartPort=war.target%4;CivilRoute(CivilBattleGlobal(war),ports[war.target].name+" / ORBITAL WAR");}
 void CivilNavigateFaction(int enemy){var f=civilization.factions[enemy];var port=ports[f.port];Vector3 n=new Vector3(.18f,.94f,-.29f).normalized;chartSystem=port.system;chartPort=port.index;CivilRoute(port.global+n*(port.radius+1200),port.name+" / "+f.name+" CAPITAL",port,n);}
}
